struct FragOut_s
{
	float4 flColor : COLOR;
};

struct VertIn_s
{
	float4 flPos : POSITION;
	float4 flTexCoord0 : TEXCOORD0;
};

FragOut_s main( in VertIn_s IN, 
			   uniform sampler2D DecalTex : TEXUNIT0 )
{
	FragOut_s OUT;

	float4 flColor = tex2D( DecalTex, IN.flTexCoord0.xy );

	float flColor1 = ( ( flColor.r + flColor.g + flColor.b )/ 0.5f );
	flColor1 = 2.0f * (flColor1 - .5f);//expand( flColor1 );
	//flColor1 = flColor1/.001f;
	OUT.flColor.rgb = 0.2f - flColor1;
	OUT.flColor.a = 1;//OUT.flColor.rgb - 1;
	
	return OUT;
}

struct VertOut_s
{
	float4 flPos : POSITION;
	float4 flTexCoord0 : TEXCOORD0;
};


VertOut_s main( in float4 flPos : POSITION,
			   in float4 flTexCoord0 : TEXCOORD0,
			   uniform float4x4 ModelViewProj )
{
	VertOut_s OUT;
	OUT.flTexCoord0 = flTexCoord0;

	OUT.flPos = mul( ModelViewProj, flPos );

	return OUT;
}

struct FragOut_s
{
	float4 flColor : COLOR;
};

struct VertIn_s
{
	float4 flPos : POSITION;
	float4 flTexCoord0 : TEXCOORD0;
};

FragOut_s main( in VertIn_s IN, 
			   uniform sampler2D DecalTex : TEXUNIT0 )
{
	FragOut_s OUT;

	float4 flColor = tex2D( DecalTex, IN.flTexCoord0.xy );

	float flColor1 = ( ( flColor.r + flColor.g + flColor.b )/ 0.5f );
	flColor1 = expand( flColor1 );
	//flColor1 = flColor1/.001f;
	OUT.flColor.rgb = 0.2f - flColor1;
	OUT.flColor.a = 1;//OUT.flColor.rgb - 1;
	
	return OUT;
}

struct FragOut_s
{
	float4 flColor : COLOR;
};

struct VertIn_s
{
	float4 flPos : POSITION;
	float4 flTexCoord0 : TEXCOORD0;
	float4 flTexCoord1 : TEXCOORD1;
	float4 flTexCoord2 : TEXCOORD2;
	float4 flTexCoord3 : TEXCOORD3;
};

FragOut_s main( in VertIn_s IN, 
			   uniform sampler2D OffsetTex : TEXUNIT0,
			   uniform sampler2D Identity : TEXUNIT1,
			   uniform sampler2D DecalTex : TEXUNIT2,
			   uniform sampler2D MaskTex : TEXUNIT3,
			   uniform float4 TexOffset )
{
	FragOut_s OUT;

	float4 flColor= tex2D( OffsetTex, IN.flTexCoord0 );

	float4 flPrevLookup = tex2D( Identity, flColor.gb );


	OUT.flColor = offsettex2D( DecalTex, IN.flTexCoord2.xy, flPrevLookup, TexOffset );
	
	OUT.flColor.a = 1;
	
	float flMask = tex2D( MaskTex, IN.flTexCoord3.xy ).r;


	OUT.flColor = OUT.flColor *( flMask );
	
	return OUT;
}

struct FragOut_s
{
	float4 flColor : COLOR;
};

struct VertIn_s
{
	float4 flPos : POSITION;
	float4 flTexCoord0 : TEXCOORD0;
	float4 flTexCoord1 : TEXCOORD1;
	float4 flTexCoord2 : TEXCOORD2;
	float4 flTexCoord3 : TEXCOORD3;
};

FragOut_s main( in VertIn_s IN, 
			   uniform sampler2D OffsetTex : TEXUNIT0,
			   uniform sampler2D Identity : TEXUNIT1,
			   uniform sampler2D DecalTex : TEXUNIT2,
			   uniform sampler2D MaskTex : TEXUNIT3,
			   uniform float4 TexOffset )
{
	FragOut_s OUT;

	float4 flColor= tex2D( OffsetTex, IN.flTexCoord0.xy );

	float2 flTex = IN.flTexCoord1.xy + TexOffset.xy * flColor.xx + TexOffset.zw *flColor.yy;
	OUT.flColor = tex2D( DecalTex, flTex.xy );
	OUT.flColor.a = 1;

	
	float flMask = tex2D( MaskTex, IN.flTexCoord3.xy ).r;


	OUT.flColor = OUT.flColor *( flMask );
	
	return OUT;
}

struct VertOut_s
{
	float4 flPos : POSITION;
	float4 flTexCoord0 : TEXCOORD0;
	float4 flTexCoord1 : TEXCOORD1;
	float4 flTexCoord2 : TEXCOORD2;
	float4 flTexCoord3 : TEXCOORD3;
};


VertOut_s main( in float4 flPos : POSITION,
			   in float4 flTexCoord0 : TEXCOORD0,
			   uniform float4x4 ModelViewProj,
			   in uniform float flScreen)
{
	VertOut_s OUT;
	OUT.flTexCoord0 = flTexCoord0;
//	OUT.flTexCoord0.y = flTexCoord0.y * ( 1024 );
	OUT.flTexCoord1 = flTexCoord0;
	OUT.flTexCoord2 = flTexCoord0;
	OUT.flTexCoord2.y = flTexCoord0.y + ( flScreen );
	OUT.flTexCoord3 = flTexCoord0;

	OUT.flPos = mul( ModelViewProj, flPos );

	return OUT;
}

