!!ARBfp1.0
OPTION ARB_precision_hint_fastest;
ATTRIB tex0 = fragment.texcoord[0];
ATTRIB tex1 = fragment.texcoord[1];
ATTRIB tex2 = fragment.texcoord[2];
ATTRIB tex3 = fragment.texcoord[3];
PARAM scaler = { 4, 4, 2, -1 };
OUTPUT outColor = result.color;
TEMP eyevec, lightvec;
TEMP specdot, col, res;
TEX eyevec, tex0, texture[0], CUBE;
MAD eyevec.rgb, eyevec, scaler.b, scaler.a;
TEX lightvec, tex1, texture[1], 2D;
MAD lightvec.rgb, lightvec, scaler.b, scaler.a;
DP3_SAT specdot.a, eyevec, lightvec;
POW specdot.a, specdot.a, scaler.r;
TEX col, tex2, texture[2], 2D;
TEX res, tex3, texture[3], 2D;
MUL res.rgb, col, res;
MUL_SAT outColor, res, specdot.a;
END

!!ARBfp1.0
OPTION ARB_precision_hint_fastest;
ATTRIB tex_camdir = fragment.texcoord[0];
ATTRIB tex_lightmap = fragment.texcoord[1];
ATTRIB tex_face = fragment.texcoord[3];
PARAM scaler = { 16, 8, 2, -1 };
OUTPUT outColor = result.color;
TEMP vec, halfvec;
TEMP specdot, color;
TEX vec, tex_lightmap, texture[1], 2D;
MAD vec.rgb, vec, scaler.b, scaler.a;
DP3 halfvec.x, tex_camdir, tex_camdir;
RSQ halfvec.x, halfvec.x;
MUL halfvec, tex_camdir, halfvec.x;
ADD halfvec, halfvec, vec;
DP3 halfvec.w, halfvec, halfvec;
RSQ halfvec.w, halfvec.w;
MUL halfvec.xyz, halfvec, halfvec.w;
TEX vec, tex_face, texture[0], 2D;
MAD vec.rgb, vec, scaler.b, scaler.a;
DP3_SAT specdot.a, vec, halfvec;
POW specdot.a, specdot.a, scaler.r;
TEX color, tex_lightmap, texture[2], 2D;
MUL_SAT color, color, specdot.a;
TEX vec, tex_face, texture[3], 2D;
MUL outColor, color, vec;
END
